with exploded as (select id, host, log_ts, level, latency_ms, status_code, attr_key, attr_value from app_logs lateral view outer explode(context) e as attr_key, attr_value) select log_ts, latency_ms, status_code, attr_value, avg(latency_ms) over (partition by attr_key, level order by cast(log_ts as bigint) range between 1800 preceding and current row) as latency_ms_avg_30m, corr(status_code, latency_ms) over (partition by attr_key) as corr_status_code_latency_ms, corr(latency_ms, status_code) over (partition by level, host) as corr_latency_ms_status_code from exploded;
